15	// ─── Markdown Tokenizer ───────────────────────────────────────────────────────
16	
17	type HeadingToken = { type: 'h1' | 'h2' | 'h3' | 'h4'; id: string; text: string }
18	
19	type Token =
20	  | HeadingToken
21	  | { type: 'hr' }
22	  | { type: 'code'; lang: string; text: string }
23	  | { type: 'table'; headers: string[]; rows: string[][] }
24	  | { type: 'ul'; items: string[]; depth: number }
25	  | { type: 'ol'; items: string[]; start: number }
26	  | { type: 'paragraph'; text: string }
27	  | { type: 'callout'; variant: 'info' | 'tip' | 'caution'; text: string }
28	  | { type: 'step'; number: number; title: string }
29	  | { type: 'blank' }
30	
31	function slugify(text: string): string {
32	  return text.toLowerCase().replace(/[^a-z0-9\s-]/g, '').trim().replace(/\s+/g, '-')
33	}
34	
35	function tokenize(md: string): Token[] {
36	  const tokens: Token[] = []
37	  const lines = md.split('\n')
38	  let i = 0
39	
40	  while (i < lines.length) {
41	    const line = lines[i]
42	
43	    // Blank
44	    if (line.trim() === '') { i++; continue }
45	
46	    // Headings
47	    const hm = line.match(/^(#{1,4})\s+(.+)$/)
48	    if (hm) {
49	      const level = hm[1].length
50	      const rawText = hm[2].replace(/\s+#+\s*$/, '')
51	      const type = (['h1', 'h2', 'h3', 'h4'] as const)[level - 1]
52	
53	      // Detect step pattern: "### Step 1: Title" or "### 1. Title"
54	      const stepMatch = rawText.match(/^(?:Step\s+)?(\d+)[.:]\s*(.+)$/i)
55	      if (level >= 3 && stepMatch) {
56	        tokens.push({ type: 'step', number: parseInt(stepMatch[1], 10), title: stepMatch[2] })
57	        i++; continue
58	      }
59	
60	      tokens.push({ type, id: slugify(rawText), text: rawText })
61	      i++; continue
62	    }
63	
64	    // Horizontal rule
65	    if (line.match(/^[-*_]{3,}\s*$/)) {
66	      tokens.push({ type: 'hr' })
67	      i++; continue
68	    }
69	
70	    // Blockquote / callout (> **Info:** text, > **Tip:** text, > **Caution:** text)
71	    if (line.match(/^>\s/)) {
72	      const blockLines: string[] = []
73	      while (i < lines.length && (lines[i].match(/^>\s/) || lines[i].match(/^>$/))) {
74	        blockLines.push(lines[i].replace(/^>\s?/, ''))
75	        i++
76	      }
77	      const fullText = blockLines.join('\n').trim()
78	      // Detect callout variant
79	      const calloutMatch = fullText.match(/^\*\*(Info|Tip|Caution|Warning|Note)[:.]?\*\*\s*([\s\S]*)$/i)
80	      if (calloutMatch) {
81	        const label = calloutMatch[1].toLowerCase()
82	        const variant = (label === 'tip' ? 'tip' : label === 'caution' || label === 'warning' ? 'caution' : 'info') as 'info' | 'tip' | 'caution'
83	        tokens.push({ type: 'callout', variant, text: calloutMatch[2].trim() })
84	      } else {
85	        tokens.push({ type: 'callout', variant: 'info', text: fullText })
86	      }
87	      continue
88	    }
89	
90	    // Fenced code block
91	    if (line.match(/^```/)) {
92	      const lang = line.slice(3).trim()
93	      const codeLines: string[] = []
94	      i++
95	      while (i < lines.length && !lines[i].match(/^```\s*$/)) {
96	        codeLines.push(lines[i])
97	        i++
98	      }
99	      i++ // skip closing ```
100	      tokens.push({ type: 'code', lang, text: codeLines.join('\n') })
101	      continue
102	    }
103	
104	    // Table
105	    if (line.startsWith('|')) {
106	      const tableLines: string[] = []
107	      while (i < lines.length && lines[i].trimStart().startsWith('|')) {
108	        tableLines.push(lines[i])
109	        i++
110	      }
111	      if (tableLines.length >= 2) {
112	        const parseRow = (r: string) =>
113	          r.split('|').slice(1, -1).map(c => c.trim()).filter((_, idx, arr) => idx < arr.length)
114	        const headers = parseRow(tableLines[0])
115	        const rows: string[][] = []
116	        for (let j = 2; j < tableLines.length; j++) {
117	          rows.push(parseRow(tableLines[j]))
118	        }
119	        tokens.push({ type: 'table', headers, rows })
120	      }
121	      continue
122	    }
123	
124	    // Unordered list
125	    if (line.match(/^(\s*)[-*+]\s/)) {
126	      const items: string[] = []
127	      const depth = line.match(/^(\s*)/)?.[1].length ?? 0
128	      while (i < lines.length && lines[i].match(/^(\s*)[-*+]\s/)) {
129	        items.push(lines[i].replace(/^(\s*)[-*+]\s/, ''))
130	        i++
131	      }
132	      tokens.push({ type: 'ul', items, depth })
133	      continue
134	    }
135	
136	    // Ordered list
137	    if (line.match(/^\d+\.\s/)) {
138	      const items: string[] = []
139	      const start = parseInt(line.match(/^(\d+)/)?.[1] ?? '1', 10)
140	      while (i < lines.length && lines[i].match(/^\d+\.\s/)) {
141	        items.push(lines[i].replace(/^\d+\.\s/, ''))
142	        i++
143	      }
144	      tokens.push({ type: 'ol', items, start })
145	      continue
146	    }
147	
148	    // Paragraph
149	    const paraLines: string[] = []
150	    while (
151	      i < lines.length &&
152	      lines[i].trim() !== '' &&
153	      !lines[i].match(/^#{1,4}\s/) &&
154	      !lines[i].match(/^```/) &&
155	      !lines[i].trimStart().startsWith('|') &&
156	      !lines[i].match(/^(\s*)[-*+]\s/) &&
157	      !lines[i].match(/^\d+\.\s/) &&
158	      !lines[i].match(/^[-*_]{3,}\s*$/) &&
159	      !lines[i].match(/^>\s/)
160	    ) {
161	      paraLines.push(lines[i])
162	      i++
163	    }
164	    if (paraLines.length > 0) {
165	      tokens.push({ type: 'paragraph', text: paraLines.join('\n') })
166	    }
167	  }
168	
169	  return tokens
170	}
